    75  void BufferOutputStream::reserveBytesUpfront(v_buff_size count) {
    76
    77    v_buff_size capacityNeeded = m_position + count;
    78
    79    if(capacityNeeded > m_capacity) {
    80
    81      v_buff_size newCapacity = utils::Binary::nextP2(capacityNeeded);
    82
    83      if(newCapacity < 0 || (m_maxCapacity > 0 && newCapacity > m_maxCapacity)) {
    84        newCapacity = m_maxCapacity;
    85      }
    86
    87      if(newCapacity < capacityNeeded) {
    88        throw std::runtime_error("[oatpp::data::stream::BufferOutputStream::reserveBytesUpfront()]: Error. Unable to allocate requested memory.");
    89      }
    90
    91      auto newData = new v_char8[static_cast<unsigned long>(newCapacity)];
    92
    93      std::memcpy(newData, m_data, static_cast<size_t>(m_position));
    94      delete [] m_data;
    95      m_data = newData;
    96      m_capacity = newCapacity;
    97
    98    }
